INSERT INTO knowledge (user_id,app_system,problem_type,problem_summary,keyword,solution,is_public) VALUES (1,'OA 办公系统','登录问题','OA 系统登录不上怎么办？','登录,密码,OA','先确认账号密码是否正确，再检查是否被锁定，连续 5 次错误会锁定 30 分钟。管理员可在「用户管理」里解锁。',1);
INSERT INTO knowledge (user_id,app_system,problem_type,problem_summary,keyword,solution,is_public) VALUES (1,'办公设备','硬件故障','打印机卡纸如何处理？','打印机,卡纸','关闭电源，打开后盖或纸盒取出卡纸，注意不要硬拉，清理纸屑后重启打印机。',1);
INSERT INTO knowledge (user_id,app_system,problem_type,problem_summary,keyword,solution,is_public) VALUES (1,'网络','网络故障','VPN 连接失败提示 691 错误','VPN,691,远程','691 一般是账号或密码错误，或账号已过期。请确认密码后重试，仍失败请联系 IT 重置。',1);
INSERT INTO knowledge (user_id,app_system,problem_type,problem_summary,keyword,solution,is_public) VALUES (1,'OA 办公系统','权限申请','如何申请新的软件安装权限？','软件,安装,权限','在 OA 提交「软件安装申请」，部门主管审批后由 IT 统一安装，请勿自行下载安装。',1);
INSERT INTO knowledge (user_id,app_system,problem_type,problem_summary,keyword,solution,is_public) VALUES (1,'邮件系统','邮箱问题','邮箱容量满了怎么清理？','邮箱,容量,清理','先删除带大附件的邮件并清空「已删除」文件夹；仍不足可申请扩容。',0);
